import React, { useState } from "react";
import FormControl from "../Form/FormControl";
import Stack from "../Stack";
import Select, { SelectOption } from "./Select";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Select> = {
  id: "Components/Select",
  title: "Components/Select",
  component: Select,
  render: (args) => {
    const options = [
      { label: "Option 1", value: "option1" },
      { label: "Option 2", value: "option2" },
      { label: "Option 3", value: "option3" },
    ];
    return (
      <div className="w-288">
        <Select {...args} options={options}></Select>
      </div>
    );
  },
  argTypes: {
    defaultValue: { control: false },
    disabled: { control: "boolean", description: "If true, the input will be disabled" },
    invalid: { control: "boolean", description: "If true, the input will indicate an error" },
    mode: {
      control: { type: "select" },
      options: ["AUTO", "CUSTOM", "NATIVE"],
      description: "Choose mode to switch from native html to full custom or automatic fallback",
    },
    size: {
      control: { type: "select" },
      options: ["small", "medium"],
      description: "The size of the input",
    },
    valid: { control: "boolean", description: "If true, the input will indicate a success" },
  },
  args: {
    "aria-label": "Select an option",
    placeholder: "Choose an option",
  },
};

export default meta;
type Story = StoryObj<typeof Select>;

export const Basic: Story = {
  tags: ["visual-test"],
};

export const Modes: Story = {
  render: () => {
    const options = [
      { label: "Option 1", value: "option1" },
      { label: "Option 2", value: "option2" },
      { label: "Option 3", value: "option3" },
    ];
    return (
      <Stack spacing="2-x" className="w-288">
        <FormControl label="AUTO (default)" required>
          <Select
            placeholder="Choose an option"
            aria-label="Select an option"
            defaultValue="option1"
            options={options}
          ></Select>
        </FormControl>
        <FormControl label="NATIVE" required>
          <Select
            placeholder="Choose an option"
            aria-label="Select an option"
            defaultValue="option1"
            mode="NATIVE"
            options={options}
          ></Select>
        </FormControl>
        <FormControl label="CUSTOM" required>
          <Select
            placeholder="Choose an option"
            aria-label="Select an option"
            defaultValue="option1"
            mode="CUSTOM"
            options={options}
          ></Select>
        </FormControl>
      </Stack>
    );
  },
};

export const Variants: Story = {
  tags: ["visual-test"],
  render: () => {
    const options = [{ label: "A320", value: "A320" }];
    return (
      <Stack spacing="2-x" className="w-288">
        <Select disabled options={options} defaultValue="disabled"></Select>
        <FormControl error errorText="Not available" required>
          <Select options={options} defaultValue="A320"></Select>
        </FormControl>
        <FormControl success successText="Available" required>
          <Select valid options={options} defaultValue="A320"></Select>
        </FormControl>
      </Stack>
    );
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
};

export const Size: Story = {
  render: () => {
    const options = [
      { label: "Medium", value: "medium" },
      { label: "Small", value: "small" },
    ];
    return (
      <Stack spacing="2-x" className="w-288">
        <Select options={options} defaultValue="medium"></Select>
        <Select size="small" options={options} defaultValue="small"></Select>
      </Stack>
    );
  },
};

export const Placeholder: Story = {
  render: () => {
    const options = [
      { label: "Option 1", value: "option1" },
      { label: "Option 2", value: "option2" },
      { label: "Option 3", value: "option3" },
    ];
    return (
      <div className="w-288">
        <Select placeholder="Choose an option" options={options}></Select>
      </div>
    );
  },
};

export const GroupedOptions: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    type LanguageOption = SelectOption & { year: string };
    const options: LanguageOption[] = [
      { label: "Smalltalk", value: "smalltalk", year: "1972" },
      { label: "C", value: "c", year: "1972" },
      { label: "SQL", value: "sql", year: "1972" },
      { label: "Python", value: "python", year: "1991" },
      { label: "Visual Basic", value: "visualbasic", year: "1991" },
      { label: "Java", value: "java", year: "1995" },
      { label: "JavaScript", value: "js", year: "1995" },
      { label: "PHP", value: "php", year: "1995" },
      { label: "Scala", value: "scala", year: "2003" },
      { label: "Groovy", value: "groovy", year: "2003" },
    ];
    return (
      <div className="w-288">
        <Select
          placeholder="Choose an option"
          options={options}
          groupBy={(option) => (option as LanguageOption).year}
          mode="NATIVE"
        ></Select>
      </div>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const options = [
      { label: "Option 1", value: "option1" },
      { label: "Option 2", value: "option2" },
      { label: "Option 3", value: "option3" },
    ];
    const [selectedValue, setSelectedValue] = useState("option3");
    return (
      <div className="w-288">
        <Select
          placeholder="Choose an option"
          aria-label="Select an option"
          options={options}
          value={selectedValue}
          onChange={(event: any, value: string) => setSelectedValue(value)}
        ></Select>
      </div>
    );
  },
};
